mapper.select:

where del_flag = '0'

    and stock_month    >=   to_date(#{beginStockMonth},'yyyy-MM')


    and stock_month     <=   to_date(#{endStockMonth},'yyyy-MM')

and embryo_code = #{embryoCode}
and stock_num = #{stockNum}


where del_flag = '0'
and id != #{id}

    and stock_month = #{stockMonth}

and embryo_code = #{embryoCode}

mapper.update:
merge into t_cx_month_stock a USING (
select #{ITEM.stockMonth,jdbcType=VARCHAR} stock_month, #{ITEM.embryoCode,jdbcType=VARCHAR} embryo_code, #{ITEM.stockNum,jdbcType=DOUBLE} stock_num, #{ITEM.overTimeStock,jdbcType=DOUBLE} over_time_stock, #{ITEM.createBy,jdbcType=VARCHAR} create_by, #{ITEM.createTime,jdbcType=DATE} create_time, #{ITEM.updateBy,jdbcType=VARCHAR} update_by, #{ITEM.updateTime,jdbcType=DATE} update_time, #{ITEM.remark,jdbcType=VARCHAR} remark, #{ITEM.bomDataVersion,jdbcType=VARCHAR} bom_data_version from dual
) b ON (a.stock_month = b.stock_month and a.embryo_code = b.embryo_code and a.bom_data_version = b.bom_data_version and a.del_flag = '0') WHEN MATCHED THEN UPDATE SET a.stock_num = b.stock_num, a.over_time_stock = b.over_time_stock, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.stock_month, a.over_time_stock, a.embryo_code, a.stock_num , a.create_by , a.create_time , a.remark, a.del_flag, a.bom_data_version ) values (SEQ_CX_MONTHSTOCK.NEXTVAL, b.stock_month, b.over_time_stock, b.embryo_code, b.stock_num, b.create_by, sysdate, b.remark, '0', b.bom_data_version )
